    if (hasValue) return [cell[0]];
    const anyReview = COL.REVIEW_SOURCES.some(c => String(data[i][c - 1]) === 'REVIEW');
    return [anyReview ? 'REVIEW' : ''];
  });

  const valueOut = pOut.map(c => [typeof c[0] === 'string' && c[0].startsWith('=') ? '' : c[0]]);
  const formulaOut = pOut.map(c => [typeof c[0] === 'string' && c[0].startsWith('=') ? c[0] : '']);
  pRange.setValues(valueOut);
  pRange.setFormulas(formulaOut);

  // --- Step 3: Rebuild "Final" ---
  const finalData = raw.getRange(2, 1, numRows, lastCol).getValues()
    .map(r => padRow(r, lastCol));
  const keep = finalData.filter(r =>
    String(r[COL.REVIEW - 1]) === 'OK' && String(r[COL.SUPERSEDED - 1]) === ''
  );

  let finalSheet = ss.getSheetByName('Final');
  if (!finalSheet) {
    finalSheet = ss.insertSheet('Final');
  } else {
    finalSheet.clearContents();
  }
  finalSheet.getRange(1, 1, 1, lastCol).setValues([headers]);
  if (keep.length) {
    finalSheet.getRange(2, 1, keep.length, lastCol).setValues(keep);
  }

  const supersededCount = supersededOut.filter(r => r[0] === 'SUPERSEDED').length;

  // --- Step 4: Append to Logs sheet ---
  let logs = ss.getSheetByName('Logs');
  if (!logs) {
    logs = ss.insertSheet('Logs');
    logs.getRange(1, 1, 1, 5).setValues([[
      'Run timestamp', 'Rows processed', 'Superseded', 'Exported to Final', 'TIME_WINDOW_MIN'
    ]]);
  }
  logs.appendRow([new Date(), numRows, supersededCount, keep.length, TIME_WINDOW_MIN]);

  try {
    SpreadsheetApp.getActive().toast(
      `Final: ${keep.length}. Superseded: ${supersededCount}. Window: ${TIME_WINDOW_MIN} min.`
    );
  } catch (e) { /* no UI, skip toast */ }
}
```

**What changed:**

- **Prompt.** `SpreadsheetApp.getUi().prompt(...)` runs on interactive runs and asks you to confirm or change the window. OK with a valid positive number overrides the constant; Cancel, empty input, or non-numeric input keeps the default. The whole prompt is wrapped in try/catch so the script also works from triggers or the Apps Script editor's "Run" when no UI is attached.
- **Logs sheet.** Created on first run with a header row. Each run appends: run timestamp, rows processed, superseded count, rows exported to Final, and the window used.
- Everything else (batch P writes, padding to 16 cols, name+time clustering, formula preservation, no deletions, Final overwrite) is unchanged.

One small note: `appendRow` writes a real `Date` object for the timestamp, which Sheets will display using the Logs sheet's locale/date format. If you want a specific string format (e.g., ISO), say the word and I'll swap it in.

```javascript
function cleanAndExport() {
  let TIME_WINDOW_MIN = 10; // default; may be overridden by prompt below

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName('Raw');
  if (!raw) throw new Error('Sheet "Raw" not found.');

  // Optional interactive prompt.
  try {
    const ui = SpreadsheetApp.getUi();
    const resp = ui.prompt(
      'Time window (minutes)',
      `Confirm or change the name+time duplicate window. Default: ${TIME_WINDOW_MIN}`,
      ui.ButtonSet.OK_CANCEL
    );
    if (resp.getSelectedButton() === ui.Button.OK) {
      const n = Number(resp.getResponseText().trim());
      if (!isNaN(n) && n > 0) TIME_WINDOW_MIN = n;
    }
  } catch (e) { /* no UI, keep default */ }

  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const sheetLastCol = raw.getLastColumn();
  const lastCol = Math.max(sheetLastCol, 16);

  // Column map (1-based):
  // 1=A Timestamp, 2=B Name, 3=C Email, 4=D JoinedBefore, 5=E Phone,
  // 6=F PreferredPark, 7=G YN_clean, 8=H Phone_clean, 9=I TS_clean,
  // 10=J Park_clean, 11=K emailKey, 12=L nameKey, 13=M DUP-email,
  // 14=N DUP-name-time, 15=O Superseded, 16=P Review
  const COL = {
    TS_CLEAN: 9, EMAIL_KEY: 11, NAME_KEY: 12,
    SUPERSEDED: 15, REVIEW: 16,
    REVIEW_SOURCES: [7, 8, 9, 10],
  };

  const numRows = lastRow - 1;

  const padRow = (row, n) =>
    row.length >= n ? row : row.concat(new Array(n - row.length).fill(''));

  const headers = padRow(raw.getRange(1, 1, 1, sheetLastCol).getValues()[0], lastCol);
  const data = raw.getRange(2, 1, numRows, sheetLastCol).getValues()
    .map(r => padRow(r, lastCol));

  const tsNum = v => {
    if (v instanceof Date) return v.getTime();
    if (typeof v === 'number' && !isNaN(v)) {
      return Math.round((v - 25569) * 86400 * 1000);
    }
    return NaN;
  };

  const windowMs = TIME_WINDOW_MIN * 60 * 1000;

  // Capture prior SUPERSEDED values so we can count NEW ones later
  const priorSuperseded = data.map(r => String(r[COL.SUPERSEDED - 1] || ''));

  // --- Step 1a: SUPERSEDED by email ---
  const latestByEmail = {};
  data.forEach((row, i) => {
    const key = String(row[COL.EMAIL_KEY - 1] || '').trim();
    const t = tsNum(row[COL.TS_CLEAN - 1]);
    if (!key || isNaN(t)) return;
    if (!latestByEmail[key] || t > latestByEmail[key].ts) {
      latestByEmail[key] = { ts: t, rowIdx: i };
    }
  });

  const supersededOut = data.map(r => [r[COL.SUPERSEDED - 1]]);

  data.forEach((row, i) => {
    const key = String(row[COL.EMAIL_KEY - 1] || '').trim();
    const t = tsNum(row[COL.TS_CLEAN - 1]);
    if (!key || isNaN(t)) return;
    const latest = latestByEmail[key];
    supersededOut[i][0] = (latest && i !== latest.rowIdx) ? 'SUPERSEDED' : '';
  });

  // --- Step 1b: SUPERSEDED by nameKey + time window (no-email rows) ---
  const noEmailByName = {};
  data.forEach((row, i) => {
    const email = String(row[COL.EMAIL_KEY - 1] || '').trim();
    if (email) return;
    const name = String(row[COL.NAME_KEY - 1] || '').trim();
    const t = tsNum(row[COL.TS_CLEAN - 1]);
    if (!name || isNaN(t)) return;
    (noEmailByName[name] = noEmailByName[name] || []).push({ ts: t, rowIdx: i });
  });

  Object.values(noEmailByName).forEach(entries => {
    if (entries.length < 2) return;
    entries.sort((a, b) => a.ts - b.ts);
    const used = new Set();
    for (let a = 0; a < entries.length; a++) {
      if (used.has(a)) continue;
      const cluster = [entries[a]];
      for (let b = a + 1; b < entries.length; b++) {
        if (used.has(b)) continue;
        if (entries[b].ts - cluster[cluster.length - 1].ts <= windowMs) {
          cluster.push(entries[b]);
        }
      }
      if (cluster.length > 1) {
        const keeperRow = cluster[cluster.length - 1].rowIdx;
        cluster.forEach(e => {
          used.add(entries.indexOf(e));
          if (e.rowIdx !== keeperRow) supersededOut[e.rowIdx][0] = 'SUPERSEDED';
        });
      } else {
        used.add(a);
      }
    }
  });

  raw.getRange(2, COL.SUPERSEDED, numRows, 1).setValues(supersededOut);

  // Count NEWLY superseded: now SUPERSEDED but wasn't before
  const newlySupersededCount = supersededOut.reduce((acc, r, i) =>
    acc + ((r[0] === 'SUPERSEDED' && priorSuperseded[i] !== 'SUPERSEDED') ? 1 : 0), 0);

  // --- Step 2: Batch-fill P where blank and no formula ---
  const pRange = raw.getRange(2, COL.REVIEW, numRows, 1);
  const pValues = pRange.getValues();
  const pFormulas = pRange.getFormulas();

  let newReviewWrites = 0;
  const pOut = pValues.map((cell, i) => {
    const hasFormula = pFormulas[i][0] !== '';
    const hasValue = cell[0] !== '' && cell[0] !== null;
    if (hasFormula) return [pFormulas[i][0]];
    if (hasValue) return [cell[0]];
    const anyReview = COL.REVIEW_SOURCES.some(c => String(data[i][c - 1]) === 'REVIEW');
    if (anyReview) {
      newReviewWrites++;
      return ['REVIEW'];
    }
    return [''];
  });

  const valueOut = pOut.map(c => [typeof c[0] === 'string' && c[0].startsWith('=') ? '' : c[0]]);
  const formulaOut = pOut.map(c => [typeof c[0] === 'string' && c[0].startsWith('=') ? c[0] : '']);
  pRange.setValues(valueOut);
  pRange.setFormulas(formulaOut);

  // --- Step 3: Rebuild "Final" ---
  const finalData = raw.getRange(2, 1, numRows, lastCol).getValues()
    .map(r => padRow(r, lastCol));
  const keep = finalData.filter(r =>
    String(r[COL.REVIEW - 1]) === 'OK' && String(r[COL.SUPERSEDED - 1]) === ''
  );

  let finalSheet = ss.getSheetByName('Final');
  if (!finalSheet) {
    finalSheet = ss.insertSheet('Final');
  } else {
    finalSheet.clearContents();
  }
  finalSheet.getRange(1, 1, 1, lastCol).setValues([headers]);
  if (keep.length) {
    finalSheet.getRange(2, 1, keep.length, lastCol).setValues(keep);
  }

  const supersededCount = supersededOut.filter(r => r[0] === 'SUPERSEDED').length;

  // Runner email, blank if unavailable
  let runnerEmail = '';
  try { runnerEmail = Session.getActiveUser().getEmail() || ''; } catch (e) { runnerEmail = ''; }

  // --- Step 4: Append to Logs sheet ---
  let logs = ss.getSheetByName('Logs');
  if (!logs) {
    logs = ss.insertSheet('Logs');
    logs.getRange(1, 1, 1, 8).setValues([[
      'Run timestamp', 'Runner email', 'Rows processed',
      'Superseded (total)', 'Superseded (new this run)',
      'P newly set to REVIEW', 'Exported to Final', 'TIME_WINDOW_MIN'
    ]]);
  }
  logs.appendRow([
    new Date(), runnerEmail, numRows,
    supersededCount, newlySupersededCount,
    newReviewWrites, keep.length, TIME_WINDOW_MIN
  ]);

  try {
    SpreadsheetApp.getActive().toast(
      `Final: ${keep.length}. Superseded total/new: ${supersededCount}/${newlySupersededCount}. ` +
      `P→REVIEW new: ${newReviewWrites}. Window: ${TIME_WINDOW_MIN} min.`
    );
  } catch (e) { /* no UI, skip toast */ }
}
```

**What changed:**

- **Runner email.** `Session.getActiveUser().getEmail()` is wrapped in try/catch and defaults to `''`. Note that in many script contexts (e.g., when the script is run by a user other than the file owner, or from certain triggers) this legitimately returns an empty string — that's a Google policy, not a bug.
- **Newly superseded count.** Captured `priorSuperseded` from the sheet before writing, then counted rows where the new value is `SUPERSEDED` but the prior wasn't.
- **New P→REVIEW writes.** Incremented a counter inside the P-build loop only when a previously blank, formula-less P cell is being set to `'REVIEW'` this run.
- **Logs header** expanded to 8 columns. On existing Logs sheets from the previous version (5 columns), new runs will still append correctly — the new row will just extend into columns F–H without re-writing the header. If you want the header auto-upgraded on first run after this change, delete the Logs sheet once and let the script recreate it.
